static RAMFN uint32_t fl_status_ram(void)                /* SR1 | SR2 << 8 */
{
    fl_saved_t s; uint32_t v;
    if (fl_enter(&s)) return 0xFFFFFFFFu;
    v = fl_rdsr(0x05) | ((uint32_t)fl_rdsr(0x35) << 8);
    fl_exit(&s);
    return v;
}

void sm_poll(uint32_t now, sm_send_fn send)
{
    if (sm_hello) {
        sm_heard = now;
        if (!sm_live || sm_hello > 1) sm_full = 1;
        sm_hello = 0;
        sm_live = 1;
    }
    if (now - sm_heard >= SM_TIMEOUT) sm_live = 0;
    while (sm_live && sm_sent < sm_length) {
        int r = send(sm_buffer + sm_sent + 1, sm_buffer[sm_sent]);
        if (r == -2) break; /* busy: the rest next time */
        if (r) sm_live = 0;
        sm_sent += 1u + sm_buffer[sm_sent];
    }
    if (!sm_live || sm_sent >= sm_length) {
        sm_length = sm_sent = 0;
    } else if (sm_sent) {
        /* Move what's left to the front, so the room it freed takes new rows now (with a small buffer, waiting for
         * all of it to go first held the screen up too long). Forward copy: the data only moves down. */
        unsigned i, n = sm_length - sm_sent;
        for (i = 0; i < n; i++)
            sm_buffer[i] = sm_buffer[sm_sent + i];
        sm_length = n;
        sm_sent = 0;
    }
}

/* the voice to give up for a new one (see the top); soft: only released voices and
 * extra voices of other non-POLY parts (also ones left after a mode change).
 * Returns its index, *pp its part; NVOICE = none */
static uint32_t voice_victim(const track_t *self, int soft, track_t **pp)
{
    uint32_t p, i, best = NVOICE, cat = 4;
    for (p = 0; p < NPART; p++) {
        track_t *t = &trk[p];
        uint32_t mode = trk_vmode(t);
        uint32_t low = mode == V_POLY ? lowest_held(t) : NVOICE;
        if (soft && t == self)
            continue;
        for (i = 0; i < NVOICE; i++) {
            const voice_t *v = &t->v[i];
            uint32_t c;
            if (!v->active || v->stage == 4u)
                continue;
            if (!v->gate)
                c = 1;                                  /* released */
            else if (mode != V_POLY && i > 0)
                c = 2;                                  /* extra UNISON, or a voice left by a mode / cap change */
            else if (!soft && mode == V_POLY && i != low)
                c = 3;                                  /* held, not the bass */
            else
                continue;
            if (c < cat || (c == cat && v->age < (*pp)->v[best].age)) {
                cat = c;
                best = i;
                *pp = t;
            }
        }
    }
    return best;
}

static void trk_note_on(track_t *t, uint32_t note, uint32_t vel)
{
    uint32_t any = 0, i, mode = trk_vmode(t);
    if (t->p[P_MUTE])
        return;
    if (t->xf_on || t->eng_req != t->engine) {          /* engine switch under way: after the fade */
        for (i = 0; i < t->xp_n && t->xp_note[i] != note; i++)
            ;
        if (i == t->xp_n && t->xp_n < 4u)
            t->xp_n++;
        i = i < t->xp_n ? i : t->xp_n - 1u;             /* (full: the last one is replaced) */
        t->xp_note[i] = (uint8_t)note;
        t->xp_vel[i] = (uint8_t)vel;
        return;
    }
    note = fol_on(t, note);                             /* ((2.1) a follower's: into the chord it follows) */
    duck_note(t, note);                                 /* (Skiff) a hit another track may duck under */
    t->hits++;                                          /* ((Skiff Q6) QUARK's event display) */
    vel = mod_note(t, note, vel);                       /* the matrix's VEL / KEY / RAND ((1.3) VEL as a destination) */
    for (i = 0; i < NVOICE; i++)
        any |= t->v[i].gate;
    if (!any)                                           /* fresh phrase: LFO retrigger and fade */
        lfo_restart(t);
    if (mode == V_POLY) {
        voice_t *v = voice_alloc(t, note);
        t->nmono = 0;                                   /* no stale mono stack after a mode change */
        t->mono_note = 0;
        v->fine = 0;
        voice_start(t, v, note, vel, t->p[P_GLIDE] != 0 && !ENGINES[t->engine]->oneshot);
        return;
    }
    {
        uint32_t sounding = t->mono_note && t->v[0].active && t->v[0].gate, want;
        mono_remove(t, note);
        if (t->nmono >= 8u)
            mono_remove(t, t->mono_stack[0]);
        t->mono_stack[t->nmono++] = (uint8_t)note;
        want = mono_pick(t);
        if (sounding && want == t->mono_note)
            return;                                     /* LOW / HIGH priority: this key does not win */
        if (mode == V_MONO)                             /* MONO: always retrigger, glide when GLIDE is set */
            mono_play(t, want, vel, 1, t->p[P_GLIDE] != 0 || t->slide_glide);
        else                                            /* LEGATO / UNISON: glide only between held notes */
            mono_play(t, want, vel, !sounding, sounding && (t->p[P_GLIDE] != 0 || t->slide_glide));
    }
}

/* note n moved down onto the track's scale (ROOT, SCALE): QNT SNAP's keys and QNT SEQ's sequenced notes */
static int32_t scale_snap(const track_t *t, int32_t n)
{
    uint32_t mask = scale_mask(t), guard = 12;
    while (guard-- && !((mask >> (uint32_t)((n - t->p[P_ROOT] + 120) % 12)) & 1u))
        n--;
    return n;
}

/* a recorded note into step s: REC (rec_note) and Skiff's TAKES (ui_take.c) merge alike */
static void rec_put(track_t *t, step_t *s, uint32_t note, uint32_t vel)
{
    uint32_t k;
    if (drum_track(t)) {                            /* DRUM: into the grid (hits) */
        uint32_t l = drum_lane(note);
        if (s->time != ST_NOTE || (!s->n && !s->hit)) {
            s->n = s->hit = s->acc = 0;
            s->flags = 0;
            s->vel = 0;
        }
        s->time = ST_NOTE;
        if (note == DRUM_LANE_NOTE[l]) {            /* a lane's note: its hit */
            s->hit |= (uint8_t)(1u << l);
            if (vel > 110)
                s->acc |= (uint8_t)(1u << l);
        } else {                                    /* another GM drum (a low tom, a crash): a note */
            for (k = 0; k < s->n && s->note[k] != note; k++)
                ;
            if (k == s->n) {
                if (s->n < 4u)
                    s->n++;
                s->note[s->n - 1u] = (uint8_t)note;
            }
            if (vel > 110)
                s->flags |= SF_ACCENT;
        }
    } else {
        if (s->time != ST_NOTE || !s->n || trk_vmode(t) != V_POLY) {
            s->n = 0;                               /* a fresh step */
            s->flags = 0;
            s->vel = 0;
        }
        for (k = 0; k < s->n && s->note[k] != note; k++)
            ;
        if (k == s->n) {
            if (s->n < 4u)
                s->n++;
            s->note[s->n - 1u] = (uint8_t)note;
        }
        s->time = ST_NOTE;
        if (vel > 110)
            s->flags |= SF_ACCENT;
    }
    if (vel > s->vel)
        s->vel = (uint8_t)vel;
}

static track_t *midi_track(uint32_t ch)
{
    int32_t k = song.g[G_ROUTE] ? -1 : midi_slot(ch);
    return k >= 0 ? &trk[k] : TSEL;
}

static void mix_part(track_t *t, uint32_t n SM_DECL)
#endif
{
    int32_t *b = SM(b);
    uint32_t i;
#if FELUCCA_CPU2
    uint32_t nr;
#endif
    mod_begin(t);                                       /* the matrix's per-block values into t->p (mod.c) */
    t->lpan_on = drum_engine(t->engine) && lanes_panned(t);   /* ((2.0, #36) a kit with a lane panned: mix_spread) */
    t->spread_on = !t->lpan_on && t->p[P_SPRD] > 0 &&   /* ((1.3) mix_spread; (2.0) a panned kit's lanes, not SPREAD) */
                   (trk_vmode(t) == V_POLY || trk_vmode(t) == V_UNISON);
#if FELUCCA_CPU2
    vs_sm[(uint32_t)(t - trk) % NPART] = sm;            /* ((#21) smx_render's sums) */
    nr = track_render(t, b, n);
    part_cost[(uint32_t)(t - trk) % NPART] = (uint16_t)(nr * ENG_VCOST[t->engine % NENGINES] + (nr || t->tail ? 60u : 0u));
    if (nr)
#else
    if (track_render(t, b, n))
#endif
        t->tail = t->p[P_ITYPE] ? 64 : 16;              /* blocks of DIST / INSERT state to run out after the last
                                                         * voice ((1.3) the INSERT's: 46 ms, a flanger's feedback) */
    else if ((!t->tail || !(t->p[P_DIST] | t->p[P_ITYPE]) || !--t->tail) && !slicer_busy(t)) {
        slicer_track(t, 0, n);                          /* (the SLICER's step clock runs on) */
        if (t->ins_run && !t->p[P_ITYPE])
            ins_rest(t);                                /* ((1.3) TYPE OFF while silent: no fade-out left for the next
                                                         * note) */
        if (MOD(t).on)
            mod_end(t);
        return;
    }
    if (t->spread_on | t->lpan_on) {                   /* ((1.3) SPREAD: its own mix, mix_spread; (2.0) a kit panned) */
        mix_spread(t, b, n SM_ARG(sm));
        if (MOD(t).on)
            mod_end(t);
        return;
    }
    {
        int32_t lvl = LEVEL_Q12[t->p[P_LEVEL] & 127], pan = t->p[P_PAN];
        int32_t gl = 4096 - (pan > 0 ? pan * 64 : 0), gr = 4096 + (pan < 0 ? pan * 64 : 0);
        int32_t c = t->p[P_CHOR] * 258, d = t->p[P_DLY] * 258, r = t->p[P_REV] * 258, pk = t->peak;
        int32_t xmax = c > d ? c : d;
        xmax = 0x7FFFFFFF / ((xmax > r ? xmax : r) | 1);   /* sends: loud chords at a high LEVEL */
        track_dist(t, b, n);
        if (t->p[P_ITYPE] | t->ins_run)
            track_insert(t, b, n);                      /* ((1.3) the INSERT: off, nothing) */
        slicer_track(t, b, n);                          /* slicer.c: before the level, pan and sends */
        if (((pf.mute >> (t - trk)) & 1u) || t->p[P_MUTE] || pf.mg[t - trk] != 32768)   /* perform.c (RAM): a black */
            AUDIO_FAR(perf_mute)((uint32_t)(t - trk), b, n);   /* key held, (2.0) a MUTE, the ramp back */
        if ((duck_on >> (t - trk)) & 1u)
            duck_apply((uint32_t)(t - trk), b, n);      /* (Skiff) duck.c: under its source's hits */
        for (i = 0; i < n; i++) {
            int32_t x = ((b[i] >> 2) * lvl) >> 10, a = x < 0 ? -x : x;   /* pre-shift: 8 loud voices */
            int32_t xs = clamp(x, -xmax, xmax);         /* sends: mulq15 would overflow */
            if (a > pk)
                pk = a;
            if (c)
                SM(c)[i] += mulq15(xs, c);
            if (d)
                SM(d)[i] += mulq15(xs, d);
            if (r)
                SM(v)[i] += mulq15(xs, r);
            SM(l)[i] += (x * gl) >> 12;
            SM(r)[i] += (x * gr) >> 12;
        }
        t->peak = pk;
    }
    if (MOD(t).on)
        mod_end(t);                                     /* the stored values back */
}

void fm1_alnk0_irq(void)                       /* via isr_alnk0 (hal/fm1_isr.S) */
{
    uint8_t p;
    uint32_t t0;
    felucca_dbg.in_audio = 1;                   /* first: TIMER5 nests from here on (main.c) */
    p = fm1_audio_pending();
    t0 = fm1_ticks();
    t5_nested_ticks = 0;
    fm1_audio_ack_aux(p);
    if (p & FM1_AUDIO_HALF) {
        uint32_t half = fm1_audio_free_half(), b, us;
        int32_t *o = &abuf[half * HALF_WORDS];
        if (shed_req) {
            shed_req = 0;
            shed_voice();
        }
#if FELUCCA_UAC
        uac_render_start();
#endif
        for (b = 0; b < HALF_FRAMES; b += CTL) {
#ifdef FM1_INPUT_LAT
            kb_out_tick = t0 + (HALF_FRAMES + b) * DAC_TICKS;   /* when this block plays (seq.c kb_lat) */
#endif
            audio_block(o + 2u * b, CTL);
        }
        fm1_audio_ack_half();
        audio_halves++;
        us = shed_check(fm1_ticks() - t0);
        if (us > audio_max_us)
            audio_max_us = us;
        {
            uint32_t load = song.cpu_q8 * (CPU_AVG - 1u) + (us * 256u) / (HALF_FRAMES * 1000000u / FS) + audio_cpu_rem;
            song.cpu_q8 = load / CPU_AVG;
            audio_cpu_rem = load % CPU_AVG;
        }
        if (fm1_audio_free_half() != half)
            felucca_dbg.late++;                         /* the DMA moved on while we rendered */
        felucca_dbg.halves++;
        felucca_dbg.last_us = us;
        if (us > felucca_dbg.max_us)
            felucca_dbg.max_us = us;
        felucca_dbg.cpu_q8 = song.cpu_q8;
    }
    felucca_dbg.in_audio = 0;
}

static uint32_t proj_hash(const void *p, uint32_t n)   /* FNV-1a over n bytes */
{
    const uint8_t *b = (const uint8_t *)p;
    uint32_t i, s = 0x811C9DC5u;
    for (i = 0; i < n; i++)
        s = (s ^ b[i]) * 16777619u;
    return s;
}

static void upf_empty(void)
{
    memset(&upf, 0, sizeof upf);
    upf.magic = UPF_MAGIC;
    upf.ver = 1;
    upf.nslot = UP_SLOTS;
}

static int bk_head(uint32_t i, bk_hdr_t *h)        /* sector i's commit record valid: 0 */
{
    if (bk_read(bk_sector(i), h, sizeof *h))
        return -1;
    return h->magic == BK_MAGIC && h->chunk < BK_CHUNKS && h->len == BK_LEN &&
           h->hsum == proj_hash(h, sizeof *h - 4u) ? 0 : -1;
}

static void cv_rect(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t c)
{
    int32_t x1 = x + w, y1 = y + h + cv_oy, i;
    uint16_t sc = swap16(c);
    y += cv_oy;                             /* clipped once, then filled row by row */
    if (x < 0)
        x = 0;
    if (y < 0)
        y = 0;
    if (x1 > (int32_t)cv_w)
        x1 = (int32_t)cv_w;
    if (y1 > (int32_t)cv_h)
        y1 = (int32_t)cv_h;
    for (; y < y1; y++)
        for (i = x; i < x1; i++)
            cv_px[(uint32_t)y * cv_w + (uint32_t)i] = sc;
}

static void ui_say(const char *a, const char *b)
{
    uint32_t n;
    str_cpy(ui.msg, a, sizeof ui.msg);
    n = str_len(ui.msg);
    str_cpy(ui.msg + n, b, sizeof ui.msg - n);
    ui.msg_t = MSG_T;
    ui.msg2[0] = 0;
    ui.take_t = 0;                                     /* (Skiff: a newer word ends the TAKE box: an undo, a notice) */
    ui.undo_w = 0;                                     /* (.. and the undo window: OCT- / OCT+ the octave again) */
}

static void motion_set_enabled(track_t *t, uint32_t on)
{
    uint32_t f = motion_guard(), b = 1u << trk_index(t);
    motion.on = (uint8_t)(on ? motion.on | b : motion.on & ~b);
    if (!on) motion_restore(t);
    motion_unguard(f);
}

/* .. stopped: track k onto entry e brings its sound now. No undo step (the song's, as the pattern) */
static void esnd_go(uint32_t k, uint32_t e)
{
    track_t *t = &trk[k % NTRK];
    if (!esnd_make(k, lists.snd[k % NTRK][e % NENT], &esnd[k % NTRK]))
        return;
    mom_back(t);
    motion_restore(t);
    fm1_irq_off();
    esnd_put(t, &esnd[k % NTRK]);
    fm1_irq_on();
    motion_rebase(t);
    if (t == TSEL)
        sync_reload = 1;
}

/* track k on its entry e now (stopped): what the track had kept, then the entry's pattern ((#28) a REST: no steps, no
 * automation, on no pattern, its LEN DIV as they were: a song's rest, stage_entry), ((2.0, #30) its sound first). 0, 1
 * an empty entry, 2 without its automation, 4 PATTERNS FULL (nowhere to keep what the track had) */
static int ent_go(uint32_t k, uint32_t e)
{
    uint32_t id = ent_pat(k, e);
    k %= NTRK;
    if (!ent_on(k, e))
        return 1;
    if (trk_keep(k))
        return 4;
    lists.cur[k] = (uint8_t)(e % NENT);
    esnd_go(k, e);
    if (id != PAT_NONE)
        return pat_load(&trk[k], id);
    track_defaults_steps(&trk[k]);                 /* (its automation too, motion_lost with it: motion_clear) */
    trk[k].p[P_SGATE] = TP[P_SGATE].def;           /* ((2.0.2) notes put here start at 1 STEP, whatever pattern's 50 %
                                                    * GATE the track had; its LEN DIV stay: a rest's length) */
    trk_pid[k] = 0;
    bk.gen++;
    return 0;
}

static void bank_poll(void)
{
    uint32_t k;
    for (k = 0; k < NTRK; k++)
        bank_poll_trk(k);
}

/* slot's name -> b (PROJ_NAME_LEN + 1 bytes); 0 = an empty slot (b ""); ((2.0) one of a format of before: OLD FORMAT).
 * Uses proj_scratch */
static int project_name(uint32_t slot, char *b)
{
    b[0] = 0;
    if (!proj_import(&proj_scratch, &proj_slot[slot & 3u], sizeof(project_store_t))) {
        if (!proj_old(slot))
            return 0;
        str_cpy(b, "OLD FORMAT", PROJ_NAME_LEN + 1u);
        return 1;
    }
    proj_name_get(b, (const uint8_t *)proj_scratch.name);
    return 1;
}

/* playing, nothing staged for track k (q not armed): entry e staged, launch mode m; a song's (adv) after reps passes of
 * the one playing. 0 staged, 1 an empty entry, 2 .. without its automation (AUTOMATION FULL), 4 PATTERNS FULL (new
 * steps there and no id for them; what went out at its last swap still waiting in q, bank_poll_trk). (#29) No waiting
 * slot is held for the swap: one a track was, and the song stages its tracks T1 first, so a pattern waiting to be
 * written kept the last track on its entry for good. (1.2.1, #12) The song's on an
 * empty entry (song_poll: a rest), (#28) any on a REST: silence, no automation, the track's own LEN DIV SWING GATE DIR,
 * so the rest's REPS count passes of the length the track has; on no pattern (trk_pid 0), so nothing is kept unless it
 * was recorded into */
static int stage_entry(uint32_t k, uint32_t e, uint32_t m, uint32_t adv, uint32_t reps)
{
    track_t *t = &trk[k];
    launch_t *q = &launch_q[k];
    uint32_t id = ent_pat(k, e), full = 0, i, same;
    if (q->done || (!trk_pid[k] && !seq_is_empty(t) && pool_alloc() == NPAT))
        return 4;
    if ((adv == 2u || !bank_used(k, e)) && (adv || ent_rest(k, e))) {   /* ((2.0) adv 2: SONG ONCE's end, a rest on e
                                                                            * whatever it names: song_poll) */
        for (i = 0; i < NSTEP; i++)
            step_clear(&q->step[i]);
        for (i = 0; i < 5u; i++)                   /* ((2.0.2) GATE the default, as ent_go's) */
            q->time[i] = BK_TIME[i] == P_SGATE ? TP[P_SGATE].def : motion_base_value(t, BK_TIME[i]);
        memset(&q->motion, 0, sizeof q->motion);
        id = PAT_NONE;
    } else if (id == PAT_NONE || pat_decode(t, id, q->step, q->time, &q->motion))
        return 1;
    same = id != PAT_NONE && id == trk_pat(k);     /* ((2.0.3, #71) the pattern the track is on: it goes on as the
                                                    * track has it, edits made before or after this copy (launch_swap) */
    if (!same && motion.count - motion_count(t) + q->motion.count > MOTION_MAX) {
        q->motion.count = 0;                       /* (no room: the steps come in, not the automation) */
        full = 1;
    }
    q_sig[k] = 0;                                  /* (the track's sig once it is in: as trk_keep packs it then) */
    if (bk_pack_raw(bk_rec, k, q->step, q->time, &q->motion, (q->motion.on >> k) & 1u)) {
        if (full)
            rec_motion_of(bk_rec, id);
        q_sig[k] = proj_hash(bk_rec, BK_REC);
    }
    q->slot = (uint8_t)e;
    q->id = (uint8_t)id;
    q->mlost = (uint8_t)full;
    q->mode = (uint8_t)m;
    q->at = launch_at(m);
    q->adv = (uint8_t)adv;
    q->reps = (uint8_t)reps;
    q->done = 0;
    q->snd = (uint8_t)(adv != 2u && esnd_make(k, lists.snd[k][e % NENT], &esnd[k]));   /* ((2.0, #30) its sound, made
                                                                                       * now: in at the swap) */
    q->same = (uint8_t)same;
    q_lsig[k] = list_sig(k);
    RING_PUBLISH();
    q->armed = 1;
    bk.gen++;
    return full ? 2 : 0;
}

/* track k to its entry e (SONG's OCT+, PERFORM's keys: the selected track; (Skiff W3) the editor's LIST PLAY): at once
 * stopped, staged playing (LAUNCH says when it comes in); what happened, said (a load takes no undo copy: what the track
 * had is kept); bank_switch's rc */
static int entry_go(uint32_t k, uint32_t e)
{
    uint32_t b0, b1;
    char b[8] = {'T', (char)('1' + k % NTRK), ' ', (char)('A' + (ent_block(k, e, &b0, &b1) ? b0 : e % NENT)), 0};
    int staged = song.playing, rc = bank_switch(k, e);   /* ((2.0, #44) a chain: its first part's, said) */
    if (rc == 1) {
        ui_say(b, " EMPTY");
        return rc;
    }
    if (rc == 4) {
        ui_way("PATTERNS FULL", WAY_PATTERNS);
        return rc;
    }
    if (staged)
        ui_say(b, LAUNCH_AT[launch_mode()]);
    else
        ui_say(rc == 2 ? "AUTOMATION FULL " : "LOADED ", b);
    str_cpy(ui.msg2, staged && rc == 2 ? "AUTOMATION FULL" : "", sizeof ui.msg2);
    return rc;
}

/* ---- (phase 5) SEQ > SONG (ui.c sg; ui_input.c sends OCT+ OCT- EDIT here): the selected track's entry picked ---- */
/* "T2 C" (b: 8 bytes) */
static void song_tag(char *b, uint32_t k, uint32_t e)
{
    b[0] = 'T';
    b[1] = (char)('1' + k % NTRK);
    b[2] = ' ';
    b[3] = (char)('A' + e % NENT);
    b[4] = 0;
}

/* .. what OCT+ does there: the entry played ("PLAY"), the pick put into it ("SET 07", "SET REST"), a copy of its
 * pattern made for it ("COPY 06 TO 17"), ((2.0) a new one, "NEW 22"; COPY+'s after it, "COPY 06 TO 22 AT F"; (#30) the
 * track's sound on it, "SET SOUND PIANO", or "SET NO SOUND") */
static void sound_name(const track_t *t, char *b);    /* (ui_draw.c) */
/* (2.0, #30) a song entry's sound by its name (b: lists.snd's two bytes, bank.c esnd_make): a user sound's or a
 * preset's (s holds 16); "" none */
static void esnd_name(const uint8_t *b, char *s)
{
    uint32_t e = b[0] - 1u, u = b[0] & 127u;
    s[0] = 0;
    if (b[0] & 128u) {
        if (u < UP_SLOTS && up_used(u))
            up_name(u, s);
    } else if (eng_ok(e) && ENGINES[e]->npresets) {
        str_cpy(s, ENGINES[e]->presets[preset_orig(ENGINES[e], b[1] % ENGINES[e]->npresets)].name, 16);
    }
}

static void up_slot_label(char *b, uint32_t k)  /* "U07" */
{
    b[0] = 'U';
    b[1] = (char)('0' + (k + 1u) / 10u);
    b[2] = (char)('0' + (k + 1u) % 10u);
    b[3] = 0;
}

/* the record's name = name (at most 12), 0 or "": the automatic one */
static void up_set_name(up_rec_t *r, uint32_t k, const char *name)
{
    char b[16];
    uint32_t i;
    if (!name || !name[0]) {
        up_auto_name(b, r->engine, k);
        name = b;
    }
    memset(r->name, 0, sizeof r->name);
    for (i = 0; i < 12u && name[i]; i++)
        r->name[i] = name[i];
}

static uint32_t btn_hold(uint32_t *t0, uint32_t label, uint32_t now, int hold_ok)
{
    uint32_t tap;
    if ((fm1_in.buttons >> panel.btn[label]) & 1u) {
        if (!*t0)
            *t0 = (now | 1u) & ~2u;
        else if (hold_ok && !(*t0 & 2u) && now - (*t0 & ~3u) > (uint32_t)HOLD_MS[settings_hold % 4u] * 1000u * FM1_TICKS_PER_US) {
            *t0 |= 2u;
            return BT_HOLD;
        }
        return BT_NONE;
    }
    tap = *t0 && !(*t0 & 2u);
    *t0 = 0;
    return tap ? BT_TAP : BT_NONE;
}

static int step_tied(const step_t *s, uint32_t k) { return (step_ties(s) >> k) & 1u; }   /* (2.0, #25) note k goes on */
static int32_t note_at(const step_t *s, uint32_t p)  /* (2.0) the note of pitch p in step s (its index), -1: none */
{
    uint32_t k;
    for (k = 0; k < s->n; k++)
        if (s->note[k] == p)
            return (int32_t)k;
    return -1;
}

/* .. a held note on into step s: its own tie beside what is there (own; no room: 0), else a TIE into an empty step */
static int take_tie(step_t *d, uint32_t note, int own)
{
    if (own)
        return ed_add(d, note, 1);
    if (!d->n && !d->hit) {
        d->time = ST_TIE;
        d->flags = 0;
        d->vel = 0;
    }
    return 1;
}

/* the notes of pass want of track k's log into steps tmp (LEN len), as REC merges them; ((2.0, #44) carry: a chain's
 * part, the notes held on into it from the pass before go on from its first step, *tied set). How many went in */
static uint32_t take_notes(uint32_t k, step_t *tmp, uint32_t len, uint32_t want, int own, int carry, uint32_t *tied)
{
    track_t *t = &trk[k % NTRK];
    uint32_t n = take_ev_n, first = n > TAKE_EV ? n - TAKE_EV : 0u, i, s, end, notes = 0;
    for (i = first; i < n; i++) {
        const take_ev_t *e = &take_ev[i % TAKE_EV];
        step_t *d;
        if (e->trk != k || !e->vel)
            continue;
        if (carry && e->pass < want && !drum_track(t)) {
            for (end = take_carry_end(k, i, n, want, len, own), s = 0; s < end && s < len && take_tie(&tmp[s], e->note, own); s++)
                *tied = 1;
            continue;
        }
        if (e->pass != want || e->step >= len)
            continue;
        d = &tmp[e->step];
        if (rec_feel && !(((1u << d->n) - 1u) & ~step_ties(d)) && !d->hit)
            d->nudge = e->feel;                       /* (Skiff) FEEL: a step with no note starting plays where its */
        rec_put(t, d, e->note, e->vel);               /* note was played */
        notes++;
        if (drum_track(t))
            continue;                                 /* (hits: no holds) */
        end = take_hold_end(k, i, n, want, len, own);
        for (s = e->step + 1u; s < end && s < len && take_tie(&tmp[s], e->note, own); s++)
            ;                                         /* ((2.0) its own tie on each, beside what is there; no room: it
                                                       * ends. Else a held note ties on into empty steps only: a take is
                                                       * an overdub, it never wipes a note) */
    }
    return notes;
}

/* (2.0, #25) NOTES' edits note by note (design/TIER_B.md), on a copy of the track's steps 1..LEN unfolded (ed_open):
 * every TIE as the notes it holds, each tied, so a note is its start and one entry on each step it goes on, whatever
 * else is there. Folded back after (ed_close: a step not changed keeps its bytes; a changed one where the notes
 * sounding before all go on, and nothing else: a TIE again) and written back at once, the audio IRQ off. The copy is
 * on the main loop's stack (832 B). A TIE on step 1 (the loop's end's) stays as it is */
/* (ed_cont, ed_unfold, ed_del, ed_add: ui.c, (2.0, #44) bank.c's chain tails use them too) */
static void ed_open(step_t *w, const track_t *t, uint32_t len)
{
    uint32_t i;
    for (i = 0; i < len; i++)
        ed_unfold(&w[i], &t->step[i], i ? &w[i - 1u] : 0);
}

/* (Skiff 2.0) SHIFT held (HOME; the SMK's KNOB BANK too), and a combo of it taken: no HOME tap, no MENU after (the
 * caller drops ui_input's home_long) */
static int shift_held(void)
{
#if BOARD_SMK37
    if (smk_sh_t0)
        return 1;
#endif
    return ui.home_t0 != 0u;
}

static uint32_t step_vel(const step_t *s) { return s->vel ? s->vel : 96u; }   /* (0: a hit's, an old step's: seq.c) */
/* step i of t is selected: a start in the range with a note picked (none picked: any) */
static int sel_step(const track_t *t, uint32_t i)
{
    const step_t *s = &t->step[i % NSTEP];
    if (i < sel_lo() || i > sel_hi() || !step_starts(s))
        return 0;
    return !nsel.picked || (nsel.vp[i % NSTEP] & ((1u << s->n) - 1u) & ~step_ties(s)) != 0u;
}

/* the 27 keys from F: black or white, and the key's place among the keys of its colour (white 0..15, black
 * 0..10). The DRUM grid: white keys are steps, black keys 1..8 lanes, 9 ACC, 10 / 11 the page */
static int key_black(uint32_t k) { return (int)((0x54Au >> ((k + 5u) % 12u)) & 1u); }

/* the EDIT layer's KNOB 2 (ui_layer.c): the selected track's engine only: its factory presets, then the used user presets
 * made with it (slot order). List index of the current sound; *total the length */
static uint32_t eng_list_pos(uint32_t *total)
{
    const engine_t *en = ENGINES[TSEL->eng_req % NENGINES];
    uint32_t e = TSEL->eng_req % NENGINES, np = preset_shown(e), u = user_of(TSEL), k, n = 0;
    uint32_t cur = np ? preset_rank(en, preset_orig(en, TSEL->preset % en->npresets)) : 0u;   /* (#124: the aliases
                                        * skipped, as on PRESETS: SAMPLE 1 loads as 0, so counting it stuck KNOB 2) */
    for (k = 0; k < UP_SLOTS; k++)
        if (up_used(k) && up_engine(k) == e) {
            if (k == u)
                cur = np + n;
            n++;
        }
    *total = np + n;
    return cur;
}

/* the buffer effect to play: the last pressed of those running */
static uint32_t perf_pick(uint32_t a)
{
    uint32_t e, best = PF_N;
    a &= PF_BUF;
    for (e = 0; e < PF_M1; e++)
        if (((a >> e) & 1u) && (best == PF_N || perf_ord[e] - perf_ord[best] < 0x80000000u))
            best = e;
    return best;
}

static void motion_undo_take(track_t *t, uint32_t tag)
{
    uint32_t i = trk_index(t);
    if (tag && tag == undo_mot_tag && undo_n && !undo_back && undo.keep && undo.trk == i + 1u &&
        undo.what == UNDO_MOT && motion_sig(t) == undo.after && fm1_ms - undo.t_ms < 1500u) {
        undo_label = 0;
        return;
    }
    undo_mot_tag = tag;
    undo_push(UNDO_MOT);
    undo.trk = (uint8_t)(i + 1u);
    undo.what = UNDO_MOT;
    undo.eng = t->eng_req;
    undo.preset = t->preset;
    undo.user = t->user;
    memcpy(undo.p, t->p, sizeof undo.p);
    memcpy(undo.step, t->step, sizeof undo.step);
    memcpy(undo.fm6, fm6_patch[i], FP_SIZE);
    undo.fm6_slot = fm6_slot[i];
    undo.pid = trk_pid[i];
    motion_snapshot_track(t, &undo.motion_backup);
    undo.keep = 0;
}

/* the presets of every engine (in ENGINE_ORDER), then the used user presets, as one list (the PRESETS knob and the
 * PRESETS page browse it) */
static uint32_t preset_all_pos(uint32_t *total)          /* list index of the selected track's preset */
{
    uint32_t n = 0, cur = 0, e, r;
    for (r = 0; r < NENG_SHOWN; r++) {                  /* (engines.c ENGINE_ORDER) */
        const engine_t *en = ENGINES[e = eng_vis(r)];
        if (e == TSEL->eng_req)
            cur = n + preset_rank(en, preset_orig(en, TSEL->preset % (en->npresets ? en->npresets : 1u)));
        n += preset_listed(e);
    }
    if (user_of(TSEL) < UP_SLOTS)
        cur = n + up_rank(user_of(TSEL));
    *total = n + up_count();
    return cur;
}

static uint32_t preset_pos(uint32_t *total)
{
    uint32_t all, current = preset_all_pos(&all), n = 0, pos = 0xFFFFFFFFu;
    if (!list_mode()) { *total = all; return current; }
    for (uint32_t i = 0; i < all; i++) {
        uint32_t k, e = preset_all_at(i, &k);
        if (!preset_in_list(e, k)) continue;
        if (i == current) pos = n;
        n++;
    }
    *total = n;
    return pos == 0xFFFFFFFFu ? n : pos; /* current sound need not be in the list */
}

static uint32_t slc_count(const slc_src_t *s, uint32_t div)
{
    const slc_man_t *m = div == SLC_DIV_MAN ? slc_man_of(s) : 0;
    return div < SLC_DIV_AUTO ? 4u << div : m ? m->n : s->nauto;
}

static void ml_off(void)
{
    ui.ml.on = ui.ml.pick = 0;
    ml_arm = 0;
    ml_heard = 0;
    ui.foot_sig = 0;
}

/* (Skiff U3, N5) a family with no page on this track's engine: its button says so ("NO SCALE ON DRUM"), the page stays */
static void page_none(const char *title)
{
    char b[24];
    str_cpy(b, "NO ", sizeof b);
    str_cpy(b + 3, title, sizeof b - 3u);
    str_cpy(b + str_len(b), " ON ", sizeof b - str_len(b));
    ui_say(b, ENGINES[TSEL->eng_req % NENGINES]->name);
}

/* .. NOTES, FEEL, the grid, stopped: the cursor at c, past the end of the pattern the selected track is on (c >= its
 * LEN) or before its start, on a chain: the track on the chain's next part (its first after its last) or the one
 * before (its last before its first), c the same place counted on into it; else c as it was */
static int32_t chain_cursor(int32_t c)
{
    uint32_t k = song.sel % NTRK, e = trk_ent(k), b0, b1;
    int32_t len = trk[k].p[P_SLEN];
    if (song.playing || seq_counting() || e >= NENT || !ent_block(k, e, &b0, &b1))
        return c;
    if (ent_go(k, c < 0 ? (e > b0 ? e - 1u : b1) : (e < b1 ? e + 1u : b0)) & ~2)   /* (0, 2: on it) */
        return c;
    return c < 0 ? c + trk[k].p[P_SLEN] : c - len;
}

static void ui_input(void)
{
    uint32_t pressed = fm1_input_edges(0), notes = fm1_input_note_edges(), now = fm1_ticks(), id, b, k;
    uint32_t home, save;
    int rec_own;
    uint32_t oct;
    uint32_t lay, combo = 0, lytap, lkeys, glo, kq = 0;
    int32_t s, sel = 0, ks[4] = {0, 0, 0, 0};
    static uint32_t lock_ms;                            /* BPM LOCK: the last locked SELECT turn (fm1_ms | 1; 0 none) */
    static uint8_t home_long;                           /* Skiff: HOME held past 0.7 s, the menu closed: MENU when let go */
    fm6_poll();                                         /* FM6: PTCH turned -> its patch */
    unit_g_poll();                                      /* ((Skiff U3, R8) the unit's CLOCK MIDI IN TUNE) */
    clock_wait_poll();                                  /* (PLAY on an external clock that sends nothing: say so) */
    bank_poll();                                        /* (Skiff) a pattern switched in live: what went out kept */
    song_poll();                                        /* (Skiff phase 5) SONG: each track's next entry staged */
#if !FELUCCA_FM4 && FELUCCA_LEGACY
    for (k = 0; k < NTRK; k++)                          /* a DIGITAL sound any other way (the paths convert it */
        if (trk[k].eng_req == ENGI_DIGITAL)             /* already): FM6 (fm4_convert.c) */
            fm4_track(&trk[k]);
#endif
    perf_latch_on = ui.lock == LAYER_FX;                /* ((Skiff U2) a locked FX layer latches: MENU > FX LATCH retired) */
    fx_usb_fixed = (ui_prefs & PREF_USB_FIXED) != 0u;   /* (MENU > USB LEVEL: fx.c, audio.c) */
    rp_apply();                                         /* (MENU > CLICK, CLICK LEVEL, COUNT-IN: click.c, seq.c) */
    if (!ui.menu)
        usb_serial_apply();                             /* (MENU > USB SERIAL: when the menu has closed) */
    settings_later_poll();                              /* (Felucca #197: LIST / FAV written once the view is left) */
    follow_poll();                                      /* ((1.3, Felucca #242) the step pages follow the play position) */
    if (mom_poll(mom_down(), fx_map()))                 /* ((1.3) MOMENTARY: LFO let go (or the menu, a layer ..): back */
        ui_message("BACK");                             /* ((2.0, D 2A) over RETURN; FX's macros too, (2.0.3, #69) once
                                                         * its map has gone) */
    midi_pc_poll();                                     /* ((1.3) MIDI Program Change) */
    ml_poll();                                          /* ((1.3) MIDI LEARN: a CC came for the picked parameter) */
    if (scr_input(pressed, notes)) {                    /* MENU > SCREEN OFF: dark, or the wake gesture: swallowed */
        if (((pressed >> panel.btn[B_PLAY]) & 1u) && (song.playing || seq_counting()))
            transport_req = 2;                          /* (Skiff U1) .. but PLAY still stops the music */
        return;                                         /* (before the buttons' timers: no tap or hold after it) */
    }
    if (((pressed >> panel.btn[B_OCTUP]) & 1u) &&      /* ((1.3) MOMENTARY: OCT+ with LFO held: kept (no octave); (2.0, */
        (mom_keep(mom_down(), fx_map()) | (layer_open() == LAYER_PERF && throw_keep()))) {   /* D 2A) */
        pressed &= ~(1u << panel.btn[B_OCTUP]);         /* FX's macros, PERFORM's throws too) */
        ui_message("KEPT");
    }
    home = btn_hold(&ui.home_t0, B_HOME, now, !ui.confirm && !name_on());   /* ((Skiff U2) held over a dialog or NAME:
                                                         * no MENU, which threw them away) */
    if (home_long && !((fm1_in.buttons >> panel.btn[B_HOME]) & 1u)) {   /* (Skiff) HOME let go after its hold: the */
        home_long = 0;                                  /* MENU (first, so the layers see it this frame) */
        ui.msg_t = 0;
        ui.menu = 1;                                    /* (at the tab and row it was left at) */
        ui.confirm = 0;                                 /* (a clear dialog is cancelled, NAME too) */
        name_close();
        ui.force = 1;
        song.seq_mode = 0;
    }
    save = btn_hold(&ui.save_t0, B_SAVE, now, !ui.menu && !ui.confirm);   /* held: UNDO (ui.c undo_swap) */
    if (ui.home_t0 && ((pressed >> panel.btn[B_SAVE]) & 1u) && !ui.menu && !ui.confirm && !name_on()) {
        ui.home_t0 |= 2u;                               /* (Skiff) SHIFT (HOME held) + SAVE: TAKE (ui_take.c); no */
        ui.save_t0 |= 2u;                               /* HOME tap, no MENU, no SAVE page, no undo */
        home_long = 0;
        take_commit(song.sel);
    }
#if BOARD_SMK37
    /* (SMK-37 Pro, SMK37_UX.md extra buttons A) KNOB BANK is SHIFT: HOME held, as a button of its own. Its combos are
     * HOME's (+ SAVE TAKE, + a layer's button its lock, pressed with a layer's button held: that layer locked) and its
     * map comes after the same moment; let go it does nothing (HOME still taps home, and held opens the MENU).
     * smk_sh_t0: its press time | 1, | 2 once a combo used it */
    if (!((fm1_in.buttons >> SMK_BTN_KNOB_BANK) & 1u))
        smk_sh_t0 = 0;
    else if (!smk_sh_t0)
        smk_sh_t0 = (now | 1u) & ~2u;
    if (smk_sh_t0 && !ui.home_t0 && ((pressed >> panel.btn[B_SAVE]) & 1u) && !ui.menu && !ui.confirm && !name_on()) {
        smk_sh_t0 |= 2u;
        ui.save_t0 |= 2u;
        take_commit(song.sel);
    }
#endif
    rec_own = ui.lock == LAYER_REC;                     /* (its press closes the REC layer: no arming) */
    if (shift_held() && ((pressed >> panel.btn[B_EDIT]) & 1u) && !ui.menu && !ui.confirm && !name_on() &&
        song.seq_mode && !ui.home && (step_page(cur_page()->graph) || cur_page()->graph == GR_FEEL)) {
        pressed &= ~(1u << panel.btn[B_EDIT]);          /* ((2.0) SHIFT + EDIT on NOTES, FEEL: the selection deleted, */
        shift_mark();                                   /* not EDIT's layer locked: EDIT held + HOME still locks it) */
        home_long = 0;
        sel_delete(TSEL);
    }
    if (ui.home_t0 && !ui.menu && !ui.confirm && !name_on() && (pressed & layer_bits_all())) {
        uint32_t lb = pressed & layer_bits_all();       /* (Skiff U2) SHIFT + a layer's button: locked open (again: */
        ui.home_t0 |= 2u;                               /* closed); no HOME tap, no MENU, the button no tap */
        home_long = 0;
        layer_shift_lock(lb, now);
        pressed &= ~lb;
    }
#if BOARD_SMK37
    if (smk_sh_t0 && !ui.home_t0 && !ui.menu && !ui.confirm && !name_on() && (pressed & layer_bits_all())) {
        uint32_t lb = pressed & layer_bits_all();       /* (KNOB BANK as SHIFT + a layer's button: locked open) */
        smk_sh_t0 |= 2u;
        layer_shift_lock(lb, now);
        pressed &= ~lb;
    }
#endif
    layer_lock_input(pressed);                          /* (a button closes a locked layer) */
    layer_arm(pressed, now);
    layer_oct_open(pressed);                            /* (OCT± with a SET layer's button down: it opens now) */
    oct = oct_taps(pressed, ui.menu || ui.confirm || act_cols() || name_on() || layer_set_open() || ui.ml.on);
    oct = layer_oct(pressed, oct);                      /* (a SET layer's OCT-: put back) */
    layer_masks();                                      /* seq.c: keys pressed with a layer's button are its own */
    lay = layer_held();
    glo = lay && ui.ly == LAYER_GLO;                    /* GLO held: SELECT is the tempo, BPM LOCK or not (#58) */
    if (!layer_allowed()) {
        perf_kill = 1;                                  /* (effects off until their keys are let go) */
        perf_latched = 0;                               /* (FX LATCH: the latched ones and the macros off) */
        perf_k[0] = perf_k[1] = perf_k[2] = perf_k[3] = 0;
        (void)mom_keep(0, 1);                           /* ((2.0) at once: nothing of them to come back) */
    }
    else if (!kb_layer)
        perf_kill = 0;
    {   /* a key pressed with the button: a combo (its edge, or the ISR already took it); then not the grid's or a step's */
        static uint32_t kb_seen;
        lkeys = kb_layer & ~kb_seen;
        combo = lay && (notes || lkeys);
        kb_seen = kb_layer;
    }
    if (lay)
        lkeys |= notes & ~fm1_in.notes;                 /* (tapped and let go already) */
    notes &= ~kb_layer;
    if (lay) {                                          /* a layer's button held: keys, knobs and buttons are combos */
        combo |= (pressed & ~ly_bit(ui.ly) &            /* (REC + PLAY: PLAY plays and REC let go soon is still */
                  ~(ui.ly == LAYER_REC ? 1u << panel.btn[B_PLAY] : 0u)) != 0u;   /* a tap, it arms: as before) */
        notes = 0;                                      /* (the keys are the layer's, not the grid's or a step's) */
        if (pressed & (1u << panel.btn[B_SAVE]))       /* no UNDO, no page */
            ui.save_t0 |= 2u;
        if ((pressed & (1u << panel.btn[B_HOME])) && !ui.lock) {   /* no menu, no HOME ((Skiff U2) locked: HOME */
            ui.home_t0 |= 2u;                          /* as always, SHIFT, its tap closing the lock); (#13) the layer */
            layer_home_lock();                         /* locked, as SHIFT + its button */
        }
#if BOARD_SMK37
        if (((pressed >> SMK_BTN_KNOB_BANK) & 1u) && !ui.lock) {   /* (KNOB BANK: as HOME there) */
            smk_sh_t0 |= 2u;
            layer_home_lock();
        }
#endif
        for (k = 0; k < 4u; k++)                        /* KNOB 1..4: the layer's (ui_layer.c layer_knob) */
            if ((ks[k] = panel_enc(EN_K1 + k)) != 0)
                combo = 1;
        if (ui.ly == LAYER_PERF) {                      /* (Skiff) PERFORM: SELECT the LAUNCH point, PRESETS the */
            int32_t ls = panel_enc(EN_SELECT), lp = panel_enc(EN_PRESET);   /* KEYS (ui_layer.c) */
            if (ls || lp) {
                combo = 1;
                perf_encoders(ls, lp);
            }
        } else {
            panel_enc(EN_PRESET);                       /* (a stray turn would load another sound) */
        }
        if ((s = panel_enc(EN_ALGO)) != 0 && (ui.ly == LAYER_PERF || ui.ly == LAYER_GLO)) {   /* (one read: #102) */
            track_select((uint32_t)clamp((int32_t)song.sel + (s > 0 ? 1 : -1), 0, NTRK - 1));
            combo = 1;                                  /* (Skiff U1) PERFORM, GLO: ALGORITHM the track (its keys,
                                                         * GLO's four LEVELs follow; their OCT-: no one track's).
                                                         * The others drop it (OCT- puts back the layer's track) */
        }
        if (glo && (sel = panel_enc(EN_SELECT)) != 0)   /* GLO + SELECT: the tempo, a combo (OCT- puts it back) */
            combo = 1;
    } else if ((kq = (uint32_t)layer_knobs_quiet()) != 0) {   /* a layer letting go: KNOB 1..4 are nobody's (#39) */
        for (k = 0; k < 4u; k++)
            if (panel_enc(EN_K1 + k) != 0)
                combo = 1;                              /* (with the button let go this frame: no tap) */
    }
    lytap = layer_gesture(now, combo);
    layer_show();
    layer_keys(lkeys);
    rec_clear_poll();                                   /* ((Skiff U2) REC's CLEAR: held) */
    for (k = 0; k < 4u; k++)
        if (ks[k]) {
            layer_knob(k, ks[k]);
            ui.hot_col = (uint8_t)k;
            ui.hot_t = 40;
        }
    song.grid = (uint8_t)keys_mode();                 /* (the menu, a dialog: the keys play again; NAME: silent) */
    if (home == BT_TAP && ui.menu) {                    /* HOME (pressed, or held) closes the menu, from ABOUT too; */
        menu_close();                                   /* the release of the hold that opened it is no tap */
        home = BT_NONE;                                 /* (menu_close went HOME already) */
    } else if (home == BT_HOLD) {                       /* HOME held: leave the menu; or (Skiff, DESIGN.md: HOME held */
        if (ui.menu)                                    /* is SHIFT) the menu opens when HOME is let go, so a SHIFT */
            menu_close();                               /* combo never races it */
        else
            home_long = 1;
    }
    {                                                   /* (Skiff U5, A1) HOME held alone a moment: SHIFT's map of the
                                                         * page (not over a layer; HINTS OFF: none); past the hold too
                                                         * (home_long: let go, the MENU), a combo ends it */
        uint8_t sh = ui.home_t0 && (!(ui.home_t0 & 2u) || home_long) && !ui.menu && !ui.confirm && !name_on() && !ui.layer &&
                     !ui_hints_off && now - (ui.home_t0 & ~3u) > 250u * 1000u * FM1_TICKS_PER_US;
#if BOARD_SMK37
        sh = sh || (smk_sh_t0 && !(smk_sh_t0 & 2u) && !ui.menu && !ui.confirm && !name_on() && !ui.layer &&
                    !ui_hints_off && now - (smk_sh_t0 & ~3u) > 250u * 1000u * FM1_TICKS_PER_US);
#endif
        if (sh != ui.shift) {
            ui.shift = sh;
            ui.force = 1;
        }
    }
    if (!ui.shift && home_long && ((fm1_in.buttons >> panel.btn[B_HOME]) & 1u) && !ui.menu && !ui.confirm && !name_on())
        ui_say("LET GO: MENU", "");                     /* (held on: the hint stays; (U5) the map's footer says it) */
    if (((pressed >> panel.btn[B_PLAY]) & 1u) && (ui.menu || ui.confirm))
        play_press();                                   /* (Skiff U1) PLAY over the menu and a dialog too (they return
                                                         * before the buttons below) */
    if (ui.menu) {                                   /* SAVE / REC taps do nothing here (HOME: above) */
        if (ui.save_t0)
            ui.save_t0 |= 2u;
        ui.pg_down = 0;
        if (!ui.home_t0)
            menu_input(oct);
        return;
    }
    if (name_on() && !ui.confirm) {                     /* NAME: the keys type, KNOB 1 / 2, OCT+ / OCT- (ui_name.c); */
        if (ui.save_t0)                                 /* SAVE does nothing */
            ui.save_t0 |= 2u;
        if (((pressed >> panel.btn[B_PLAY]) & 1u) && (song.playing || seq_counting()))
            transport_req = 2;                          /* PLAY stops a transport started meanwhile (MIDI Start, the
                                                         * editor) so the name can be saved; it never starts one */
        ui.pg_down = 0;
        name_input(notes, oct);
        return;
    }
    if (save == BT_HOLD)                                /* SAVE held: undo, one level back (ui.c undo_step) */
        undo_step(0);                                   /* (Skiff: one level back; OCT- / OCT+ then: ui.undo_w) */
    else if (save == BT_TAP && !ui.confirm)             /* SAVE acts on release (a hold is the undo) */
        open_family(FAM_SAVE);
    if (ui.confirm) {                                   /* OCT- cancels, OCT+ does it; nothing else reacts */
        if (oct & 2u) {
            uint32_t kind = ui.confirm;
            ui.confirm = 0;
            ui.force = 1;
            if (kind == CF_OVR_PROJ) {                  /* overwrite: the NAME screen writes it */
                name_open(NK_PROJ_SAVE, ui.confirm_trk & 3u);
            } else if (kind == CF_OVR_USER) {
                name_open(NK_USER_SAVE, ui.confirm_trk);
            } else if (kind == CF_ERASE_USER) {
                up_ui(1u, ui.confirm_trk);
            } else if (kind == CF_ERASE_BANK) {         /* (Skiff phase 5) the pool view's CLEAR */
                pool_clear(ui.confirm_trk);
            } else if (kind == CF_EMPTY_BANK) {         /* ((2.0, #46) .. EMPTY, CLEAR UNUSED */
                pool_empty(ui.confirm_trk);
            } else if (kind == CF_CLEAR_UNUSED) {
                pool_clear_unused();
            } else if (kind == CF_CLEAR_ENTRY) {        /* (Skiff phase 5) SONG */
                song_clear(ui.confirm_trk);
            } else if (kind == CF_CLEAR_MOTION) {
                track_t *t = &trk[ui.confirm_trk % NTRK];
                undo_label = "AUTOMATION"; load_begin(t, UNDO_PAT); motion_clear(t); load_end(t); ui_message("AUTOMATION CLEARED");
            } else if (kind == CF_INIT_SOUND) {
                undo_label = "INIT"; sound_init();   /* ((Skiff phase 7) DRUM-X: the factory kit too) */
            } else if (kind == CF_LOAD_PROJ) {
                project_load(ui.confirm_trk & 3u);
            } else if (kind == CF_ERASE_PROJ) {         /* ((1.2.1, #6) SAVE > PROJECT's DELETE, NEW) */
                (void)project_erase(ui.confirm_trk & 3u);
            } else if (kind == CF_NEW_PROJ) {
                project_new();
            } else if (kind == CF_RESET_SET) {          /* ((Skiff U4, A3) MENU > SYSTEM > RESET SETTINGS) */
                settings_reset();
                ui_message("SETTINGS RESET");
            } else if (kind == CF_STORE_SCENE) {        /* (Skiff U2) PERFORM: SAVE + a white key over a scene */
                scene_saved(ui.confirm_trk);
            } else {
                track_t *t = &trk[ui.confirm_trk % NTRK];
                undo_label = "CLEAR";
                char b[24] = "PATTERN 00 CLEARED";     /* ((Skiff U4) which one: its number) */
                uint32_t id = trk_pat(ui.confirm_trk % NTRK);
                load_begin(t, UNDO_PAT);
                track_defaults_steps(t);
                load_end(t);
                t->nheld = 0;                           /* and the latched arp chord */
                t->arp_phys = 0;
                if (id < NPAT) {
                    pat_num(b + 8, id);
                    b[10] = ' ';
                } else {
                    str_cpy(b, "PATTERN CLEARED", sizeof b);
                }
                ui_message(b);
            }
        } else if (oct & 1u) {
            ui.confirm = 0;
            ui.force = 1;
        }
        ui.pg_down = 0;
        enc_drop();
        return;
    }
    if (lytap)                                          /* a layer's button acts on release (held: the layer) */
        layer_tap(lytap);
    if (home == BT_TAP)
        layer_unlock();                                 /* ((Skiff U2) HOME tapped: a locked layer closes, as before) */
    if (home == BT_TAP && ui.home) {                    /* Skiff: HOME on HOME, the tracks <-> the scope (ui_home.c) */
        ui.home_scope ^= 1u;
        ui.force = 1;
    } else if (home == BT_TAP)                          /* HOME acts on release: a hold opens the menu */
        go_home();
    cursor_fix();                                       /* LEN may have changed (knob, editor, load) */
    for (id = 0; id < FM1_NBTN; id++) {
        if (!((pressed >> id) & 1u))
            continue;
        b = panel_btn_of(id);
        switch (b) {
        case B_PLAY:
            play_press();
            break;
        case B_REC:                                     /* (Skiff U2) arms / disarms on the press, in a layer too; */
            if (!rec_own)                               /* SHIFT + REC: its layer, locked (above) */
                rec_tap();
            break;
        case B_SEQ:
        case B_SAVE:
        case B_FX:                                      /* the layers' buttons: ui_layer.c */
        case B_GLO:
        case B_SCL:
        case B_EDIT:
        case B_HOME:
            break;
        case B_OCTDN:
        case B_OCTUP: {
            uint32_t both = (1u << panel.btn[B_OCTDN]) | (1u << panel.btn[B_OCTUP]);
            if (act_cols() || layer_set_open() || ui.ml.on)   /* action pages: enter / back (below); SET layers: OCT-;
                                                         * ((1.3) MIDI LEARN: below) */
                break;
            if (shift_held() && song.seq_mode && !ui.home &&   /* ((2.0) SHIFT + OCT- / OCT+ on NOTES, FEEL: COPY, */
                (step_page(cur_page()->graph) || cur_page()->graph == GR_FEEL)) {   /* PASTE (a SHIFT combo) */
                shift_mark();
                home_long = 0;
                if (b == B_OCTDN)
                    sel_copy(TSEL);
                else
                    sel_paste(TSEL);
                break;
            }
            if (ui.undo_w) {                            /* (Skiff) the undo window: OCT- further back, OCT+ redo */
                undo_step(b == B_OCTUP);
                break;
            }
            if ((fm1_in.buttons & both) == both)
                song.octave = 0;
            else
                song.octave += b == B_OCTDN ? (song.octave > -3 ? -1 : 0) : (song.octave < 3 ? 1 : 0);
            break;
        }
        default:                                        /* page buttons (GLO SCL ENV LFO EDIT ARP): when let go */
            if (!lay)                                   /* (with FX held: swallowed) */
                ui.pg_down |= (uint16_t)(1u << id);
            break;
        }
    }
    b = ui.pg_down & ~fm1_in.buttons;
    ui.pg_down &= (uint16_t)~b;
    for (id = 0; b; id++, b >>= 1)
        if (b & 1u)
            page_tap(panel_btn_of(id));
    if (act_cols() && oct && ui.undo_w) {               /* ((Skiff U2) the undo window first, as its box says:
                                                         * OCT- further back, OCT+ redo) */
        undo_step((oct & 2u) != 0u);
    } else if (act_cols() && (oct & 2u)) {              /* action pages: OCT+ does the picked action, */
        act_do();
    } else if (act_cols() && (oct & 1u)) {              /* OCT- drops it, or (none picked) goes HOME */
        if (cur_page()->graph == GR_SONG)               /* ((Skiff phase 5) SONG: the pick, or the entry staged) */
            song_back();
        else if (ui.act)
            ui.act = ui.act2 = 0;
        else if (ui.ev_del)                             /* ((Skiff U2) AUTO LIST's DELETE) */
            ui.ev_del = 0;
        else
            go_home();
    } else if (ui.ml.on && oct) {                       /* ((1.3) MIDI LEARN: OCT- clears the picked CC, OCT+ done) */
        ml_oct(oct);
    }
    song.grid = (uint8_t)keys_mode();                 /* (seq.c: the keys are the grid's) */
#if FELUCCA_SLICE
    if (notes && slice_page_on())                       /* SLICES: a key picks the slice it plays */
        slice_keys_pick(notes);
#endif
    lock_keys();                                        /* (a grid key on a hit let go: the hit goes) */
    if (song.grid) {
        grid_keys(notes);
    } else if (song.seq_mode && step_page(cur_page()->graph)) {   /* NOTES (not FEEL: its knobs only) */
        static uint32_t wr_hint_ms;                     /* (Skiff U1) "REC: WRITE STEPS" said last (0: never) */
        int armed = (song.rec >> song.sel) & 1u;
        if (live_rec_sel() || !armed) {                 /* armed and playing: the keys record live, not
                                                         * into the cursor step too; not armed (1.2, #133): they
                                                         * play and write nothing, (2.0) a note of the selection's
                                                         * they pick (sel_keys) */
            ui.entry_open = 0;
            if (!armed && notes && sel_keys(notes))
                ui.force = 1;
            else if (!armed && notes && !ui.msg_t && (!wr_hint_ms || fm1_ms - wr_hint_ms > 10000u)) {
                ui_message("[REC] WRITE STEPS");        /* (Skiff U1) .. so say how they write, now and then */
                wr_hint_ms = fm1_ms | 1u;
            }
        } else
            seq_entry(notes);                           /* armed and stopped: step recording at the cursor */
    }

    /* #102: the knobs a layer took above are not read again here. The TIMER5 scan (10 kHz) counts detents while this
     * pass runs, so one landing after the layer's read went to the page as well: KNOB 1..4 edited the layer's control
     * and the page under it (HOME's sound, motion recorded), PRESETS could load a sound. They stay for the next pass */
    kq |= lay;
    if (!lay && (s = panel_enc(EN_PRESET)) != 0) {
        if (shift_held() && sel_shift(s)) {             /* ((2.0) SHIFT + PRESETS on NOTES, FEEL: the selection, a */
            shift_mark();                               /* SHIFT combo) */
            home_long = 0;
        } else {
            presets_turn(s);
        }
    }
    if (!lay && (s = panel_enc(EN_ALGO)) != 0)     /* ALGORITHM: the selected track, on every page */
        track_select((uint32_t)clamp((int32_t)song.sel + (s > 0 ? 1 : -1), 0, NTRK - 1));
    if ((s = glo ? sel : panel_enc(EN_SELECT)) != 0) {   /* SELECT: the tempo with GLO held (or BPM LOCK OFF, Felucca's
                                                         * way); (Skiff phase 8, rule 3) else the pages */
        int sheet = !lay && !ui.home && sheet_of(cur_page()->graph);   /* (Skiff U1) a sheet's rows: SELECT is their
                                                                        * only way, BPM LOCK or not */
        if (glo || (!(ui_prefs & PREF_BPM_LOCK) && !sheet)) {
            song.g[G_BPM] = (int16_t)clamp(song.g[G_BPM] + accel(EN_SELECT, s, 200), GP[G_BPM].min, GP[G_BPM].max);
            ui.bpm_t = 40;                              /* the header's BPM lights up; no message over the header */
        } else if (lay) {
            ;                                           /* (another layer held: not the page under it) */
        } else if (!ui.home) {
            select_turn(s);
        } else {                                        /* MENU > BPM LOCK ON (#58), on HOME (no pages): only with GLO
                                                         * held (and on GLO > GLOBAL, GLO's G4 TAP); says so once a burst */
            if (!lock_ms || fm1_ms - lock_ms > 1000u)
                ui_way("BPM LOCKED", "GLO + SELECT: TEMPO");   /* ((Skiff U4) and how) */
            lock_ms = fm1_ms | 1u;
        }
    }
    for (k = 0; k < 4u && !kq; k++) {
        const page_t *pg = cur_page();
        int16_t *hv;
        uint64_t held;
        if ((s = panel_enc(EN_K1 + k)) == 0)
            continue;
        if (mom_down())                                 /* ((1.3) LFO + a knob, MOMENTARY or not: LFO's release opens no
                                                         * page) */
            ui.pg_down &= (uint16_t)~(1u << panel.btn[B_LFO]);
        if ((held = lock_held()) != 0u) {               /* a step held on NOTES: KNOB k locks (parameter locks) */
            lock_turn(k, s, held);
            ui.hot_col = (uint8_t)k;
            ui.hot_t = 40;
            continue;
        }
        if (mom_down() && mom_turn(k, s)) {             /* ((1.3) MOMENTARY: LFO held; no automation, no undo) */
            ui.hot_col = (uint8_t)k;
            ui.hot_t = 40;
            continue;
        }
        if (ui.home || pg->scope == SC_STEP || pg->scope == SC_TRK || page_desc(pg, k, &hv) ||
            ((pg->graph == GR_USER || pg->graph == GR_BANK || pg->graph == GR_MOD) && k == 0u)
            || (pg->graph == GR_SLICES && k < 2u) || pg->graph == GR_SONG || sheet_of(pg->graph)) {   /* (not an empty
                                                         * column; (Skiff) SONG's four; a sheet's four) */
            ui.hot_col = (uint8_t)k;
            ui.hot_t = 40;
        }
        if (ui.home) {
            int16_t *vp;
            const param_desc_t *d = home_param(k, &vp);
            *vp = (int16_t)param_turn(d, *vp, accel(EN_K1 + k, s, d->fmt == F_ENUM ? 0 : d->max - d->min));
            motion_capture(TSEL, (uint32_t)(vp - TSEL->p), *vp);
            ml_knob(TSEL, (uint32_t)(vp - TSEL->p));
        } else {
            edit_param(k, s);
        }
    }
    ui_notices();
}

/* the shown tab's rows: 24 px (LARGE 28, a tab of up to 5 rows), 2 px apart (a tab of 6: 1 px, its panel then ends
 * 6 px above the key hints as the others do; the rule between two rows is that gap row). (1.3) A tab of more shows
 * MTAB_ROWS of them from mr_top, so the cursor's row is the last shown once past them (MIDI's ten) */
static uint32_t mr_n(void) { return mtab_rows(menu_tab()) < MTAB_ROWS ? mtab_rows(menu_tab()) : MTAB_ROWS; }

/* a menu row's dotted leader, as an old book's contents: a dot every 3 px from x0 to x1 */
static void cr_leader(int32_t x0, int32_t x1, int32_t y)
{
    for (; x0 < x1; x0 += 3)
        cv_rect(x0, y, 1, 1, T_DIM);
}

/* a note starts at st: a NOTE step's hit or note ((2.0, #25) one not tied on: a step whose notes all go on is a tie) */
static int step_on(const step_t *st)
{
    return st->time == ST_NOTE && (st->hit || (st->n && step_ties(st) != (1u << st->n) - 1u));
}

/* text in maxw px, ellipsised when it is longer: a label or a value should always fit (the host
 * layout lint reports a cut one), free text (cv_free_text: a preset name, a message) may be cut */
static int32_t cv_text_fit(int32_t x, int32_t y, const aafont_t *f, const char *s, uint16_t fg, uint16_t bg,
                           int32_t maxw)
{
    char b[48];
    int cut = text_fit(b, sizeof b, s, f, maxw);
    return cv_text_flags(x, y, f, b, fg, bg, cut ? 1u : 0u);
}

/* a chord's name from its root and tones (bit i: i semitones above the root): "C", "Cm7", "F#m7b5", "Gsus4",
 * "A5" -> b (12 bytes) */
static void chord_name(char *b, uint32_t root, uint32_t mask)
{
    uint32_t mi = (mask >> 3) & 1u, ma = (mask >> 4) & 1u, b5 = (mask >> 6) & 1u, p5 = (mask >> 7) & 1u;
    uint32_t s5 = (mask >> 8) & 1u, d7 = (mask >> 9) & 1u, m7 = (mask >> 10) & 1u, M7 = (mask >> 11) & 1u;
    const char *q, *x = "";
    str_cpy(b, N_NOTE[root % 12u], 12);
    if (mi && !ma && b5 && !p5)
        q = d7 ? "dim7" : m7 ? "m7b5" : "dim";
    else if (ma && !mi && s5 && !p5)
        q = m7 ? "+7" : M7 ? "+M7" : "aug";
    else if (ma && !mi)
        q = m7 ? "7" : M7 ? "maj7" : d7 ? "6" : "";
    else if (mi)
        q = m7 ? "m7" : M7 ? "mM7" : d7 ? "m6" : "m";
    else if ((mask >> 5) & 1u) {                        /* no third: suspended */
        q = m7 ? "7" : "";
        x = "sus4";
    } else if ((mask >> 2) & 1u) {
        q = m7 ? "7" : "";
        x = "sus2";
    } else
        q = "5";
    str_cpy(b + str_len(b), q, 12 - str_len(b));
    str_cpy(b + str_len(b), x, 12 - str_len(b));
}

/* (2.0, #35, design/mockups/v2_kits.png A) .. a lane of a user kit with no sample: its track empty, its name DIM */
static void lane_fader_of(const track_t *t, uint32_t i, int32_t x, int32_t y1, int32_t len, int32_t h, int sel, uint16_t c)
{
    if (drum_lane_has(t, i))
        lane_fader(x, y1, len, h, sel, c);
    else
        cv_rrect(x + 12, y1 - len, 4, len, 2, T_RAISE, T_SURF);
}

static void lane_tile(const track_t *t, uint32_t i, int32_t x, int32_t y, int sel)
{
    if (sel)
        cv_rect(x + 2, y, 24, 16, T_THEME);
    GFX_HOOK_ALIGN(x + 2, y, x + 26, y + 16, AL_HV, "lane name centred under its fader");
    cv_text_in(x + 2, y + CAP_IN(S, 16), 24, &AF_S, drum_lane_abbr(t, i), sel ? T_INK : drum_lane_has(t, i) ? T_MID : T_DIM,
               sel ? T_THEME : T_SURF);
}

static void pg_curve_graph(int32_t (*at)(const pg_curve_t *, int32_t), const pg_curve_t *k, const int32_t *w, uint16_t c)
{
    int32_t i, py = 0, pk = 0;
    int16_t ys[117];
    for (i = 0; i <= 116; i++) {                     /* (the curve; its highest point, the first) */
        ys[i] = (int16_t)(66 - at(k, (i - 58) * 32768 / 58) * 58 / 32768);
        if (ys[i] < ys[pk])
            pk = i;
    }
    if (ux.crypt) {                                  /* (CRYPT, as LFO's: the straight line faint ASCII art, the curve a
                                                      * snake, its head at the end (39 columns of 3 px, 13 lines of 9); the
                                                      * wave as OSC's: ASCII art, blood in its teeth (22 of 4, 9 of 8)) */
        uint8_t L[39], S[39], W[22];
        for (i = 0; i < 39; i++) {
            L[i] = (uint8_t)clamp(6 - at(k, (i * 2 - 38) * 32768 / 38) * 6 / 32768, 0, 12);
            S[i] = (uint8_t)(12 - i * 12 / 38);
        }
        for (i = 0; i < 22; i++)
            W[i] = (uint8_t)clamp(4 - w[i * 4] * 4 / 32768, 0, 8);
        pg_hline(12, 128, 66, T_LINE);
        cv_rect(70, 8, 1, 117, T_LINE);
        pg_hline(140, 227, 88, T_LINE);
        cr_art(12, 8, 3, 9, S, 39, T_LINE);
        cr_snake(12, 8, 3, 9, L, 38, T_THEME, CR_EMBER);   /* (its head and tongue clear of the wave) */
        for (i = 0; i + 1 < 22; i++)
            if (W[i + 1] <= W[i])
                cr_dither(140 + i * 4, 56 + W[i] * 8 + 2, 4, (8 - W[i]) * 8 - 2, CR_BLOOD);
        cr_art(140, 56, 4, 8, W, 22, T_THEME);
    } else {
        for (i = 0; i <= 116; i++) {                 /* (under the curve, as ANALOG's FLT: NEON the sun's bands, QUARK a
                                                      * Monte Carlo fill) */
            pg_under(12 + i, ys[i], 8, 124, ux_mix(c, T_SURF, 75));
        }
        pg_hline(12, 128, 66, T_LINE);
        cv_rect(70, 8, 1, 117, T_LINE);
        pg_hline(140, 227, 88, T_LINE);
        cv_line(12, 124, 128, 8, T_DIM);             /* (the straight line: no drive) */
        for (i = 1; i <= 116; i++)
            cv_line_t(12 + i - 1, ys[i - 1], 12 + i, ys[i], c, 3);
        for (i = 0; i < 88; i++) {                   /* (the wave) */
            int32_t y = 88 - w[i] * 32 / 32768;
            if (i)
                cv_line_t(140 + i - 1, py, 140 + i, y, c, 2);
            py = y;
        }
        py = 88 - w[87] * 32 / 32768;                /* (its end, as LFO's now) */
        if (ux.quark) {                              /* (QUARK: a nucleus on the curve's highest point, the electron at
                                                      * the wave's end) */
            qk_nucleus(12 + pk, ys[pk], T_THEME, 7);
            qk_disc(227, py, 3, T_ACCENT);
        } else if (ux.neon) {                        /* (NEON: a sparkle at the curve's end; a white-hot trail into one at
                                                      * the wave's) */
            ne_spark(128, ys[116] + 1, T_ACCENT, 2);
            for (i = 0; i < 24; i++)
                cv_rect(227 - i, 88 - w[87 - i] * 32 / 32768, 1, 2, ux_mix(T_TEXT, c, i * 100 / 24));
            ne_spark(227, py + 1, T_ACCENT, 1);
        }
    }
}

static int32_t lc_w = LC_W;                              /* the cells' width (FX's effects: LF_W) */
static uint16_t lc_fill(uint32_t st, uint16_t *ink)
{
    *ink = st == LS_DIM ? T_DIM : T_THEME;
    if (st == LS_MUTE) {
        *ink = T_INK;
        return T_KEY;
    }
    if (st == LS_HELD) {
        *ink = T_BG;
        return T_ACCENT;
    }
    if (st == LS_SEL || st == LS_WAIT) {
        *ink = T_INK;
        return T_THEME;
    }
    return T_RAISE;
}

/* CHIP = STEP: the voice amplitude is the stepped envelope, not the ADSR curve. The ADSR only
 * gates: held, it is kept at full; after note-off the staircase keeps running (as the chip's
 * envelope never sees a note-off) and the voice is cut when the ADSR release has fallen to 1 %
 * (about the REL time; REL 0 cuts at once) or a one-shot decay has reached 0. */
static int32_t lofi_amp(track_t *t, voice_t *v, int32_t adsr)
{
    int32_t b = t->p[P_E3] >> 2, vol = v->s[6] & 15, div = (v->s[6] >> 4) & 15;
    if (t->p[P_E0] != CHIP_STEP)
        return adsr;
    if (!v->active)                                     /* the ADSR ended it (or the voice was given up) */
        return 0;
    if (v->stage == 3u) {
        if (v->env < (1 << 24) / 100 || (b >= 1 && b <= 16 && !vol)) {
            v->env = 0;
            v->stage = 0;
            v->active = 0;
            return 0;
        }
    } else {
        v->env = 1 << 24;                               /* the release starts from full */
    }
    if (!b)
        return 15 * Q4;
    v->s[7] += (int32_t)FRAME_Q16;
    while (v->s[7] >= 65536) {
        v->s[7] -= 65536;
        if (div) {
            div--;
        } else {
            div = step_period(b);
            if (vol)
                vol--;
            else if (b > 16)
                vol = 15;
        }
    }
    v->s[6] = vol | div << 4;
    return vol * Q4;
}

/* the three formants of vowel position pos (0..127 << 8, A E I O U), Hz * 16 */
static void vowel_at(int32_t pos, int32_t *f, int32_t *b)
{
    int32_t x = (clamp(pos, 0, 127 << 8) * 33027) >> 20, i = x >> 8, fr = x & 255, j;   /* * 4 / 127 */
    if (i >= 4) {
        i = 3;
        fr = 256;
    }
    for (j = 0; j < 3; j++) {
        f[j] = (VOWEL_F[i][j] << 4) + (((VOWEL_F[i + 1][j] - VOWEL_F[i][j]) * fr) >> 4);
        b[j] = (VOWEL_B[i][j] << 4) + (((VOWEL_B[i + 1][j] - VOWEL_B[i][j]) * fr) >> 4);
    }
}

/* naive value of a wave at phase ph (the step of a sync restart) */
static int32_t trio_naive(uint32_t w, uint32_t ph, const trio_pw_t *q)
{
    switch (w) {
    case TW_TRI:
        return osc_tri(ph);
    case TW_SAW:
        return (int32_t)(ph >> 16) - 32768;
    case TW_PLS:
        return (ph < q->pw ? 32767 : -32768) - q->pdc;
    case TW_ST:
        return trio_st(ph);
    case TW_PS:
        return trio_ps(ph, q);
    default:
        return 0;
    }
}

static const param_desc_t *noise_desc(const track_t *t, uint32_t k)
{
    int32_t mode = t->p[P_E0];
    if (k == 5u && mode >= NZ_LFSR)
        return mode == NZ_LFSR ? &NOISE_LONG : &NOISE_META;
    if (k == 7u && mode >= NZ_LFSR)
        return &NOISE_CLK;
    return 0;
}

static void perf_buf_start(uint32_t e)
{
    if (!sl_lent) {
        sl_lent = 1;
        perf_drop_slicer();
    }
    pf.src = (uint8_t)e;
    pf.next = PF_N;
    pf.wr = pf.rp = 0;
    pf.odd = 0;
    pf.xn = 0;
    if (e == PF_TAPE) {
        uint32_t t = beat_samples();
        pf.mode = BM_TAPE;
        if (t > PB_TAPE)
            t = PB_TAPE;
        pf.tv = 65536;
        pf.dv = 65536u / t + 1u;
        pf.tpos = 0;
    } else if (e == PF_OUP || e == PF_ODN) {    /* (wr: the frame written next, len: frames written) */
        pf.mode = BM_HARM;
        pf.len = 0;
        pf.hph = 0;
        pf.hinc = e == PF_OUP ? 0u - (1u << 21) : 1u << 20;   /* the delay: -1 / +0.5 sample a sample */
        pf.hfb = 0;
    } else if (e == PF_FLG || e == PF_VIN) {      /* (wr, len: as OCT UP / DN's) */
        pf.mode = e == PF_FLG ? BM_FLG : BM_VIN;
        pf.len = 0;
        pf.hph = 0;
        pf.hinc = e == PF_FLG ? 0xFFFFFFFFu / (8u * beat_samples()) : 54052u;   /* a bar each way; 0.555 Hz */
        pf.vl[0] = pf.vl[1] = pf.ck = 0;
    } else if (e == PF_FRZ) {
        pf.mode = BM_FRZ;
        pf.gp[0] = 0;
        pf.gp[1] = PB_GRAIN / 2u;
        pf.gs[0] = pf.gs[1] = 0;
    } else {
        pf.mode = BM_LOOP;
        pf.state = 0;
        pf.len = perf_len(e);
        pf.rev = e == PF_REV;
    }
}

